(window.NTDATA=window.NTDATA||{});(NTDATA.rbo=NTDATA.rbo||{}).judg={"1":{"1":"После смерти Иисуса сыны Из – раилевы вопросили Господа: «Кто поведет нас на войну с ханаанеями?»","2":"Господь ответил: «Вас поведет Иуда. Я отдаю эту страну в его руки».","3":"Иуда сказал своему брату Симеону: «Иди со мною, помоги отвоевать мой надел у ханаанеев. А потом я помогу тебе в твоем наделе». И Симеон пошел вместе с Иудой.","4":"Сыны Иуды выступили в поход. Господь даровал им победу над ханаанеями и периззеями: в Безеке они перебили десять тысяч врагов.","5":"Там, в Безеке, они встретились с Адони - Безеком, сразились с ним и разгромили ханаанеев и периззеев.","6":"Адони – Безек обратился в бегство. За ним погнались, поймали и отрубили ему большие пальцы на руках и ногах.","7":"Адони – Безек сказал: «Семьдесят царей, у которых были отрублены большие пальцы рук и ног, подбирали объедки у меня под столом. Как я поступал с другими – так и Бог поступил со мной». Его увели в Иерусалим, и там он умер.","8":"Сыны Иуды напали на Иерусалим и захватили его. Всех жителей они перебили, а город сожгли.","9":"Затем они пошли войной на тех ханаанеев, что жили в горах, в Негеве и в Шефеле .","10":"Сыны Иуды напали на ханаанеев, живших в Хевроне (раньше Хеврон назывался Кирьят – Арба), и убили Шешая, Ахимана и Талмая.","11":"Оттуда они пошли в поход на жителей Девира. (Раньше Девир назывался Кирьят – Сефер.)","12":"Калев сказал: «Кто победит и захватит Кирьят – Сефер, тому я отдам в жены мою дочь Ахсу ».","13":"Город захватил Отниэл, потомок Кеназа, младший брат Калева, и Ка – лев отдал ему в жены свою дочь Ахсу.","14":"Пришла Ахса – и уговорила Отниэла просить у ее отца участок земли. «Что ты хочешь?» – спросил Калев у Ахсы, когда она соскочила с осла.","15":"«Дай мне свое благословение, – сказала Ахса. – Ты дал мне землю в Неге – ве, дай же и источники!» И Калев отдал ей источники – и верхние, и нижние.","16":"Кенеи, потомки Моисеева тестя, пошли вместе с сынами Иуды из Города Пальм в Иудейскую пустыню – в Негев, в землю арадскую, – и поселились среди живущих там.","17":"Племена Иуды и Симеона, брата его, пошли войной на ханаанеев, обитавших в Цефате, и перебили их. Они предали этот город заклятью и уничтожили. С тех пор он зовется Хорма .","18":"Племя Иуды захватило Газу и ее окрестности, Ашкелон и его окрестности, а также Экрон и его окрестности.","19":"Господь был с сынами Иуды, и они овладели горами. Но с жителями долины сыны Иуды справиться не смогли, потому что у тех были железные колесницы.","20":"Калеву, как и велел Моисей, отдали Хеврон. И Калев отнял его у трех потомков Анака.","21":"Сыны Вениамина так и не отобрали Иерусалим у евусеев. Евусеи живут в Иерусалиме, вместе с сынами Вениамина, и по сей день.","22":"Сыны Иосифа выступили в поход на Бет – Эль. Господь был с ними.","23":"Они выставили дозоры у Бет – Эля (раньше этот город назывался Луз).","24":"Увидев, как из города вышел человек, дозорные сказали ему: «Покажи нам, как проникнуть в город, и мы отплатим тебе добром за добро».","25":"Он показал, как туда проникнуть. Они перебили жителей города, а этого человека, вместе со всем его родом, отпустили.","26":"Он пришел в землю хеттов, основал там город и дал ему имя Луз; этот город зовется так и по сей день.","27":"Племя Манассии так и не овладело Бет – Шеаном, Таанахом, Дором, Ивлеамом и Мегиддо, а также селениями вокруг них. Ханаанеи остались жить там.","28":"(Позже, когда израильтяне стали сильнее, они заставили ханаанеев нести трудовую повинность, но землями их так и не овладели.)","29":"Племя Ефрема так и не отобрало Гезер у ханаанеев. Ханаанеи остались жить в Гезере, в наделе Ефрема.","30":"Племя Завулона так и не овладело Китроном и Нахалалом. Ханаанеи остались жить в наделе Завулона, но несут трудовую повинность.","31":"Племя Асира так и не овладело Акко и Сидоном, а также Ахлавом, Ахзивом, Хелбой, Афиком и Реховом.","32":"Сыны Асира стали жить среди ханаанеев, жителей этой страны, так и не сумев овладеть их землей.","33":"Племя Неффалима так и не овладело Бет – Шемешем и Бет – Анатом и стало жить среди ханаанеев, жителей этой страны. Но жители Бет – Шемеша и Бет – Аната несут трудовую повинность.","34":"Сынов Дана амореи оттеснили в горы и не давали им спуститься в долину.","35":"Амореи остались жить в Хар – Хересе, Айялоне и Шаалвиме, но когда сыны Иосифа стали сильнее, они заставили амореев нести трудовую повинность.","36":"(Аморейские земли начинаются от Скорпионова подъема и Селы.)"},"2":{"1":"Ангел Господа пришел из Гилгала в Бохим. Он сказал: «Я вывел вас из Египта и привел в ту страну, которую с клятвой обещал вашим предкам. Я сказал: „Я никогда не расторгну Своего договора с вами –","2":"а вы не заключайте договоров с жителями этой страны и разрушьте их жертвенники!\" Но вы Меня не послушались. Как могли вы так поступить?","3":"Вот и Я решил, что не буду изгонять местные народы прочь от вас. Эти народы станут для вас ловушкой, а их боги будут для вас западней!»","4":"Когда ангел Господа сказал это израильтянам, весь народ громко заплакал","5":"(потому это место и назвали Бохим). Там израильтяне принесли жертвы Господу.","6":"После того как Иисус отпустил народ, израильтяне разошлись по своим наделам. Эта земля стала их владением.","7":"Во времена Иисуса – и во времена переживших его старейшин, которые видели, какие великие дела совершил Господь для Израиля, – народ верно служил Господу.","8":"Иисус Навин, раб Господа, умер, прожив сто десять лет.","9":"Его похоронили в его владениях, в Тимнат – Хересе, что в горах Ефрема, к северу от горы Гааш.","10":"Все то поколение отошло к предкам, а на смену ему пришло новое поколение – люди, которые не знали Господа, не знали, что сделал Господь для Израиля.","11":"И начали израильтяне творить дела, ненавистные Господу: стали служить Ваалам.","12":"Оставили они Господа, Бога отцов своих, который вывел их из Египта, стали служить и поклоняться другим богам – богам окрестных народов. Всем этим они вызывали гнев Господа.","13":"Они оставили Господа, стали служить Ваалу и Астартам!","14":"Господь разгневался на израильтян, отдал их в руки притеснителей – и те притесняли их. Он отдал их в руки врагов, живших окрест, – и уже не могли израильтяне дать им отпор.","15":"Всякий раз, когда израильтяне выходили на битву, Господь посылал им неудачу – как Он и предупреждал их, как и грозил им, как и клялся. Плохо было израильтянам!","16":"Господь давал им вождей (Судей), которые избавляли израильтян от притеснителей.","17":"Но и вождей своих израильтяне не слушали: блудили с другими богами – поклонялись им! Быстро свернули они с того пути, по которому шли их отцы! Отцы соблюдали повеления Господа, а они перестали.","18":"Когда Господь посылал им вождя, Он сам был с этим вождем. Пока вождь был жив, Господь избавлял израильтян от врагов. Слыша, как стонут израильтяне под игом угнетателей и притеснителей, Господь оставлял Свой гнев.","19":"Но лишь только вождь умирал, израильтяне вновь принимались за прежнее и поступали еще хуже, чем их отцы, – почитали других богов, служили им и поклонялись. Продолжали они творить злые дела, упрямо шли по тому же пути!","20":"И Господь разгневался на них. Он сказал: «Раз этот народ Меня не слушает, раз они нарушают договор, который Я заповедал соблюдать их предкам,","21":"не уберу Я прочь ни один из тех народов, что остались здесь после смерти Иисуса».","22":"Эти народы были нужны, чтобы испытать Израиль: готовы ли израильтяне верно следовать по пути Господа, как шли их отцы?","23":"И Господь оставил в стране несколько местных народов – не стал сразу отбирать у них землю, не отдал их в руки Иисуса."},"3":{"1":"Вот народы, которые Господь оставил в этой стране, чтобы испытать израильтян, не участвовавших в завоевании Ханаана.","2":"(Лишь затем, чтобы научить военному делу те поколения израильтян, которые не участвовали в завоевании.)","3":"Это пять филистимских княжеств, а также все те ханаанеи, сидоняне и хиввеи, что живут на Ливанских горах, от горы Баал – Хермон до Лево - Хамата.","4":"Эти народы нужны были, чтобы испытать Израиль: будут ли израильтяне соблюдать повеления, которые Господь дал их предкам через Моисея?","5":"Живя среди ханаанеев, хеттов, амореев, периззеев, хиввеев и евусеев,","6":"сыны Израилевы брали их дочерей себе в жены, а своих дочерей выдавали замуж за них – и стали служить их богам.","7":"Начали израильтяне творить дела, ненавистные Господу, – забыли Господа, своего Бога, служили Ваалам и Ашерам.","8":"И Господь разгневался на них. Он отдал их в руки Кушан – Ришатаима, царя Арам – Нахараима. Восемь лет израильтяне были под властью Кушан – Ришатаима.","9":"Потом они воззвали к Господу, и Господь послал им избавителя, который их спас, – это был Отниэл, потомок Кеназа, младший брат Калева.","10":"Сошел на Отниэла дух Господа, и Отниэл стал вождем Израиля. Он выступил в поход, и Господь отдал в его руки Кушан – Ришатаима, царя Арама. Отниэл победил Кушан – Ришатаима,","11":"и на сорок лет в стране воцарился покой. Затем Отниэл, потомок Кеназа, умер.","12":"Израильтяне снова стали творить дела, ненавистные Господу, – и за то, что они творили такие дела, Господь дал Эглону, царю Моава, одолеть Израиль.","13":"Призвав на подмогу аммонитян и амалекитян, Эглон пошел на израильтян войной и, разбив их, овладел Городом Пальм.","14":"Восемнадцать лет израильтяне были под властью Эглона, царя Моава,","15":"а потом воззвали к Господу, и Господь послал им избавителя – это был Эхуд, сын Геры, из племени Вениамина. У Эхуда была увечная правая рука. Израильтяне отправили его с данью к Эглону, царю Моава.","16":"Эхуд сделал себе обоюдоострый кинжал длиной в один гомед, спрятал на правом бедре под одеждой –","17":"и явился к Эглону, царю Моава, с данью. Эглон был очень толст.","18":"Эхуд преподнес ему дань. Потом он отпустил своих людей, которые эту дань принесли,","19":"а сам, повернув назад у гилгальских истуканов, снова пришел к Эглону и сказал: «Царь, у меня к тебе тайное поручение». – «Тихо!» – сказал Эглон. Все его приближенные вышли.","20":"Эхуд поднялся в собственные покои Эглона, в его комнату на втором этаже, и сказал: «У меня к тебе поручение от Бога!» Эглон встал.","21":"Тогда Эхуд левой рукой выхватил кинжал, что был спрятан у него на правом боку, и вонзил Эглону в живот –","22":"вогнал вместе с рукояткой! Клинок целиком ушел в жир. Эхуд не стал вытаскивать кинжал. Он выбрался через лаз –","23":"выбрался через боковой ход – а дверь комнаты закрыл и запер.","24":"Как только Эхуд ушел, вернулись приближенные Эглона. Увидев, что дверь заперта, они решили, что их владыка справляет нужду у себя в комнате.","25":"Долго ждали они, но царь не открывал. Тогда они принесли ключ, отперли и увидели: их владыка лежит на полу, мертвый.","26":"А Эхуд, пока они мешкали, успел скрыться – он миновал гилгальских истуканов и бежал в Сеиру .","27":"Придя в горы Ефрема, Эхуд протрубил в рог – и спустился с гор уже во главе войска израильтян.","28":"«Скорее за мной! – говорил Эхуд. – Господь отдал ваших врагов, моавитян, вам в руки!» Израильтяне во главе с Эхудом спустились с гор и преградили моавитянам путь, захватив броды через Иордан, – и никому из врагов не удалось уйти на ту сторону.","29":"Они перебили тогда десять тысяч моавитян – людей дородных, настоящих воинов! Ни один не спасся!","30":"В тот день израильтяне взяли верх над Моавом. На восемьдесят лет в стране воцарился покой.","31":"После Эхуда был Шамгар, сын Анат. Простым рожном, каким погоняют волов, он перебил шестьсот филистимлян. Он тоже был избавителем Израиля."},"4":{"1":"Израильтяне снова стали творить дела, ненавистные Господу. (Эхуд уже умер.)","2":"И Господь отдал израильтян в руки Явина, царя ханаанского, чьей столицей был Хацор. Военачальником Явина был Сисера, который пребывал в Харошет – ха – Гоиме.","3":"Израильтяне вновь воззвали к Господу – у Сисеры было девятьсот железных колесниц, и целых двадцать лет он жестоко притеснял израильтян.","4":"В то время вождем израильтян была Девора, пророчица, жена Лаппидота. Юна сидела под Девориной Пальмой, что между Рамой и Бет – Элем, в горах Ефрема. Израильтяне приходили к ней и получали от нее указания.","6":"Девора призвала к себе Барака, сына Авиноама, из Кедеша, что в земле Неффалима, и сказала ему: «Господь, Бог Израиля, повелевает тебе: „Иди и стань на горе Фавор с десятью тысячами воинов из племен Неффалима и Завулона.","7":"Я сделаю так, что Сисера, военачальник Явина, со всеми своими колесницами, со всеми своими полчищами выйдет тебе навстречу, в Кишонскую долину, – и Я отдам его в твои руки\"».","8":"Барак ответил ей: «Если ты пойдешь со мной, то я пойду. А если нет, то и я не пойду». –","9":"«Я иду с тобой, – сказала Девора. – Но этот поход тебя не прославит: Господь отдаст Сисеру в руки женщине!» И Девора пошла вместе с Бараком в Кедеш.","10":"Туда, в Кедеш, Барак созвал племена Завулона и Неффалима; под его начало собралось десять тысяч воинов. Девора была вместе с ним.","11":"В ту пору Хевер – кеней, отделившись от племени Каина, от потомков Моисеева тестя Ховава, раскинул свои шатры у Цаананнимского дуба, близ Кедеша.","12":"Сисере донесли, что Барак, сын Авиноама, стоит на горе Фавор.","13":"И Сисера привел все свои колесницы – девятьсот железных колесниц – и всех своих воинов из Харошет – ха – Гоима в Кишонскую долину.","14":"Девора сказала Бараку: «Вперед! Настал день, когда Господь отдаст Сисеру тебе в руки. Господь идет перед тобой!» Барак с десятью тысячами воинов спустился с горы Фавор.","15":"При появлении Барака Господь привел Сисеру, и его людей на колесницах, и все его войско в ужас и смятение перед мечом. Сисера спрыгнул со своей колесницы и бросился бежать.","16":"Барак преследовал его колесницы и войско до Харошет – ха – Гоима; все воины Сисеры пали от меча, ни один не уцелел.","17":"Сисера прибежал в шатер Яэли, жены Хевера – кенея (род Хевера – кенея был в союзе с Явином, царем Хацора).","18":"Яэль вышла навстречу Сисере и сказала: «Заходи, господин мой! Заходи, не бойся!» Сисера зашел к ней в шатер. Она укрыла его покрывалом.","19":"Сисера попросил: «Дай немного воды! Пить хочется». Она развязала мех с молоком, напоила Сисеру и укрыла его.","20":"«Стой у входа в шатер, – сказал он ей. – Если подойдут и спросят, нет ли кого в шатре, отвечай: „Нет!\"»","21":"Но Яэль, жена Хевера, взяла колышек, какими крепят шатер, взяла молоток, тихонько подошла к Сисере и вогнала ему колышек в висок – пригвоздила к земле! (Сисера от усталости дремал.) Он умер на месте.","22":"Когда появился Барак, преследовавший Сисеру, Яэль вышла ему навстречу и сказала: «Пойдем, я покажу тебе того, кого ты ищешь». Барак вошел и увидел: Сисера лежит мертвый, а в виске у него – колышек.","23":"В тот день Бог даровал израильтянам победу над Явином, царем ханаанским.","24":"После этого израильтяне теснили его все больше и больше – и стерли Явина, царя ханаанского, с лица земли!"},"5":{"1":"В тот день Девора, вместе с Бараком, сыном Авиноама, пела такую песнь.","2":"За то, что Израиль вожди повели, за то, что народ в ополченье идет, благословите Господа!","3":"Внимайте, цари, услышьте, владыки! Я буду петь, о Господе петь! Я восславлю Господа, Бога Израиля!","4":"Когда Ты шел из Сеира, Господь, когда Ты шел из страны Эдом, содрогалась земля, с небес ливень лил – облака проливали дождь.","5":"Горы дрожали пред Господом Синайским, пред Господом, Богом Израиля!","6":"Во дни Шамгара, сына Анат, во дни Яэли опустели пути, путник шел окольной тропой,","7":"и вождей у Израиля не стало! Так было, пока не появилась ты, о Девора, о мать Израиля!","8":"Новых богов избрали – и вот война у ворот! Что ж не видно щитов и копий у сорока тысяч израильтян?","9":"Ликует мое сердце о правителях Израиля, о народе, что идет в ополченье! Благословите Господа!","10":"Вы, что едете на ослицах белых, вы, что сидите на чепраках, вы, что по дорогам идете, вознесите хвалу!","11":"Голоса погонщиков у колодцев: там о победах Господа поют, о победах Его вождей – вождей Израиля! Народ Господа подошел к воротам!","12":"Воспрянь же, Девора, воспрянь, воспрянь – и пой песнь! Барак, Авиноама сын, пленников в плен уводи!","13":"Уцелевшие витязи пришли, народ Господа явился на подмогу Ему, пришли воины!","14":"Шли воины Ефрема, чьи корни в Амалеке! За тобой, среди отрядов твоих, Вениамин! Шли те, кто стоит во главе Махира, и те, кому вручены жезлы вождей Завулона!","15":"Вожди Иссахара – с Деворой! Иссахар верен Бараку – вслед за ним устремился в долину! А роды Рувима – в глубоких раздумьях.","16":"Что ты сидишь меж кострищ и слушаешь дудку пастушью? Да, роды Рувима – в глубоких раздумьях!","17":"Галаад – за Иорданом живет. Зачем Дан поселился на кораблях? Асир обитает на морском берегу, у заливов живет.","18":"Вызов смерти бросает Завулон – и с ним Неффалим – высоко, в полях!","19":"И вот, вышли на битву цари, цари Ханаана вышли на бой – при Таанахе, у вод близ Мегиддо . Но не досталось им серебра!","20":"Вступили звезды небесные в бой, разили с орбит своих Сисеру !","21":"Врагов сметает река Кишон, древняя река, река Кишон! Ярость моя, попирай вражью мощь!","22":"Стучат копыта, стучат! Несутся их жеребцы!","23":"«Предайте проклятью Мероз, – ангел Господа повелел, – прокляните живущих там! Не пришли они на подмогу Господу, не пришли Ему на подмогу их воины!»","24":"Благословенна средь женщин жена Хевера – кенея, Яэль! Средь женщин, живущих в шатрах, благословенна она!","25":"Гость попросил воды – она подала молока: в чаше, достойной витязя, сливки ему поднесла.","26":"Взяла она колышек в руку, молоток работников – в десницу, ударила Сисеру ! Голову разбила ему, пробила, проломила висок!","27":"У ног ее рухнул, упал, лежит! У ног ее рухнул, пал! Рухнул – на месте мертвым упал!","28":"Глядя в окно, рыдая, говорит мать Сисеры: «Что ж не видно его колесниц? Что ж не слышно топота коней?»","29":"Отвечают ей умные женщины из свиты, и сама она отвечает себе:","30":"«Добычу взяли – и делят меж собой. По девке на каждого, а то и по две! У Сисеры добыча, цветные ткани! Добыча, цветные узорные ткани, пара одеяний узорных у него – добыча!»","31":"Да погибнут так все враги Твои, Господь! А кто любит Его – подобны солнцу, восходящему в силе своей! …И на сорок лет в стране воцарился покой."},"6":{"1":"Израильтяне стали творить дела, ненавистные Господу, и Господь на семь лет отдал их в руки мидьянитян.","2":"Тяжким было иго мидьянитян, и израильтяне устраивали себе убежища в расщелинах скал, в пещерах и на неприступных вершинах.","3":"Только, бывало, у израильтян кончится сев, как нагрянут мидьянитяне, а с ними – амалекитяне и восточные племена.","4":"Станут они лагерем на земле израильтян – и уничтожат урожай по всей стране, до самой Газы, не оставляя израильтянам ни еды, ни овец, ни быков, ни ослов.","5":"Враги приходили со своими стадами, со своими семьями – многочисленные, словно саранча. Не счесть их было, и не счесть было их верблюдов. Приходили – и грабили страну.","6":"Вконец разоренные мидьянскими набегами, израильтяне воззвали к Господу.","7":"Израильтяне взывали к Господу, прося защиты от мидьянитян,","8":"и Он послал к израильтянам пророка. Пророк сказал им: «Так говорит Господь, Бог Израиля: Я вывел вас из Египта – избавил вас от неволи,","9":"Я спас вас от египтян и от всех ваших врагов! Я всех их прогнал прочь, а их земли отдал вам!","10":"Я сказал вам: „Ваш Бог – это Я, Господь! Не служите богам амореев, народа, на чьей земле вы живете\". Но не послушали вы Меня!»","11":"Ангел Господа пришел и сел под дубом в Офре, что была во владении Иоаса из рода Авиэзера. Гедеон, сын Иоаса, в это время обмолачивал пшеницу – в давильне для винограда, чтобы мидьянитяне не заметили.","12":"Ангел Господа явился ему и сказал: «Могучий воин! С тобою Господь!»","13":"Гедеон ответил: «Прости, господин мой. Если и впрямь Господь с нами, то почему случилось такое? Где чудеса Его, о которых говорили наши отцы? Ведь они рассказывали, как Господь вывел нас из Египта! А что теперь? Господь нас оставил, отдал в руки мидьянитян!»","14":"Господь обратил на него Свой взор и сказал: «Иди, могучий, избавь Израиль от мидьянитян! Отныне ты Мой посланник».","15":"Гедеон ответил: «Прости, господин мой. Как могу я избавить Израиль, если и род мой – последний среди родов Манассии, и сам я младший в своей семье?»","16":"Господь сказал: «Я буду с тобой, и ты перебьешь мидьянитян всех до одного!»","17":"Гедеон попросил: «Если я угоден Тебе, дай знак, что это Ты, именно Ты говоришь со мною!","18":"Не уходи, пока я не вернусь, – я принесу Тебе угощение». – «Я посижу здесь и подожду тебя», – ответил гость.","19":"Гедеон пошел и приготовил мясо козленка, а из эфы муки испек пресных лепешек. Он положил мясо в корзину, налил отвар в котелок – и отнес гостю, сидевшему под дубом.","20":"«Положи мясо и лепешки на эту скалу и вылей на них отвар», – велел ему Божий ангел. Гедеон повиновался.","21":"Ангел Господа коснулся мяса и лепешек концом своего посоха – и вышел из скалы огонь, и сжег мясо и хлеб! Ангел Господа скрылся из вида.","22":"Понял тогда Гедеон, что это был ангел Господа. «О Владыка Господь, горе мне! – сказал Гедеон. – Я видел ангела Господнего лицом к лицу!»","23":"Но Господь ответил: «Все хорошо, не бойся! Ты останешься жив».","24":"На том месте Гедеон воздвиг Господу жертвенник и дал этому жертвеннику имя Яхве – Шалом (он и по сей день стоит в Офре, что в наделе Авиэзера).","25":"В ту ночь Господь сказал Гедеону: «Возьми быка из отцовского ста – да, быка откормленного, семилетнего. Разрушь принадлежащий твоему отцу жертвенник Ваала и низвергни Ашеру, которая там стоит.","26":"На той вершине воздвигни для Господа, твоего Бога, жертвенник и разложи на нем все необходимое. Взяв откормленного быка, принеси его в жертву всесожжения, а на дрова пусть пойдет низвергнутая тобою Ашера».","27":"Гедеон выбрал из числа своих людей десятерых помощников и сделал, как велел ему Господь. Но совершил он все это не днем, а ночью, потому что боялся и своих родственников, и прочих жителей селения.","28":"Наутро встали жители селения и видят: жертвенник Ваала разрушен, Ашера, что стояла рядом, низвергнута, а на новом, только что построенном жертвеннике принесен в жертву откормленный бык.","29":"«Кто это сделал?» – спрашивали люди друг у друга. Искали, доискивались – и разузнали: это сделал Гедеон, сын Иоаса.","30":"Жители селения сказали Иоасу: «Выдай нам своего сына, он должен умереть! Он разрушил жертвенник Ваала и низверг Ашеру, что стояла рядом».","31":"Но Иоас ответил тем, кто его обступил: «Вам ли защищать Ваала? Вам ли за него заступаться? Кто будет защищать его, не доживет до рассвета! Если он бог, то пусть сам поборется, когда разрушают его жертвенник!»","32":"В тот день Гедеону дали имя Иеруббаал, что означает: «Пусть Ваал поборется с ним». (Ведь он разрушил жертвенник Ваала.)","33":"Мидьянитяне, амалекитяне и восточные племена, собравшись вместе, пришли и стали лагерем в Изреельской долине.","34":"И вошел тогда в Гедеона дух Господа. Гедеон протрубил в рог – и за ним пошел род Авиэзера;","35":"разослал вестников – за ним пошло все племя Манассии; послал вестников к племенам Асира, Завулона и Неффалима – и эти племена тоже отправились на войну.","36":"Гедеон сказал Богу: «Ты действительно моей рукою спасешь Израиль, как обещал?","37":"Смотри: я кладу здесь, на току, только что состриженную шерсть. Пусть на шерсти выступит роса, а земля вокруг останется сухой – вот тогда я поверю, что Ты и в самом деле спасешь Израиль моей рукою, как обещал!»","38":"Так и случилось. Наутро Гедеон встал, принялся выжимать шерсть, и из нее потекла вода – он набрал целую чашу.","39":"Гедеон сказал Богу: «Не прогневайся, я попрошу Тебя еще об одном, последнем знамении с этой шерстью. Теперь пусть шерсть останется сухой, а на земле вокруг пусть выступит роса!»","40":"В ту ночь Бог так и сделал. Шерсть осталась сухой, а по всей земле была роса."},"7":{"1":"Рано утром Иеруббаал (то есть Гедеон) вместе со всем своим войском стал лагерем у Хародского источника. Стан мидьянитян был севернее, у горы Морэ, в долине.","2":"Господь сказал Гедеону: «Слишком много с тобой народа. Не отдам Я мидьянитян в ваши руки, а не то израильтяне возгордятся предо Мною, скажут, что они спасли себя своими силами!","3":"Объяви народу: „Кто боится и дрожит – пусть возвращается, пусть уходит с Галаадских гор!\"» Двадцать две тысячи воинов вернулись домой, а десять тысяч остались.","4":"Господь сказал Гедеону: «Народа все еще слишком много! Отведи их к источнику, и там Я отберу для тебя воинов. Про кого Я скажу тебе: „Этот пойдет с тобой!\" – тот пойдет. А про кого Я скажу: „Этот с тобой не пойдет!\" – тот останется».","5":"Когда Гедеон привел всех воинов к источнику, Господь сказал ему: «Тех, кто будет лакать воду языком, как собака, поставь по одну сторону, а по другую – тех, кто будет пить став на колени».","6":"Тех, кто лакал воду из горсти, оказалось триста человек. Все прочие пили став на колени.","7":"Господь сказал Гедеону: «Силами тех трехсот человек, которые лакали воду, Я принесу вам победу – отдам мидьянитян в твои руки! А прочие пусть расходятся по домам».","8":"У израильских воинов были с собою припасы и трубы – рога. Распустив израильтян по домам, Гедеон оставил с собою триста человек. Стан мидьянитян был внизу, в долине.","9":"В ту ночь Господь сказал Гедеону: «Спустись и напади на их стан – Я отдаю их в твои руки!","10":"А если боишься, то сходи туда со своим слугой Пурой","11":"и послушай, что они говорят. Это придаст тебе смелости, и ты нападешь на их стан!» Гедеон и его слуга Пура спустились к сторожевым постам вражеского стана.","12":"Мидьянитяне, амалекитяне и восточные племена расположились в долине – многочисленные, как саранча; не было числа их верблюдам – как песку морскому!","13":"Гедеон подошел ближе и услышал, как один человек рассказывает другому свой сон: «Мне снилось, что по мидьянскому стану катится круглый ячменный хлеб. Докатился он до шатра – и повалил его. Он опрокинул шатер, шатер рухнул!»","14":"Другой отвечал: «Это меч израильтянина Гедеона, сына Иоаса! Бог отдал в его руки мидьянитян и весь этот стан».","15":"Услышав пересказ и толкование этого сна, Гедеон пал ниц. Затем он вернулся в стан израильтян и провозгласил: «Вперед! Господь отдает мидьянский стан в ваши руки!»","16":"Гедеон разделил триста человек на три отряда. Каждому воину он дал рог и спрятанный в пустом кувшине факел.","17":"«Смотрите на меня и делайте, как я, – велел он своим воинам. – Когда я подойду к их стану, делайте то же, что буду делать я.","18":"Мы затрубим в рога – я и отряд, который будет со мною. А вы тоже трубите, вокруг всего их стана, и кричите: „За Господа и Гедеона!\"»","19":"Как только началась вторая стража ночи и во вражеском стане сменились часовые, Гедеон и та сотня, что была с ним, подойдя к самому стану, затрубили в рога и разбили свои кувшины.","20":"Все воины, во всех трех отрядах, затрубили и разбили свои кувшины! Держа в левой руке факел, а в правой рог, все они трубили и кричали: «Руби! За Господа и Гедеона!»","21":"Они стояли вокруг стана, но с места не двигались. А люди в стане засуетились, закричали и обратились в бегство.","22":"Когда затрубили три сотни рогов, Господь сделал так, что люди в стане обратили оружие друг против друга. Их войско бежало до самой Бет – ха – Шитты, в сторону Цереры, – на берег реки, к Авел – Мехоле, что близ Таббата.","23":"Собрались израильтяне – племена Неффалима и Асира, все племя Манассии – и пустились в погоню за мидьянитянами.","24":"Гедеон разослал по горам Ефрема вестников с призывом: «Спускайтесь с гор, навстречу мидьянитянам, и преградите им путь к реке – займите берег Иордана вплоть до Бет – Бары!» Ефремляне собрались и преградили путь к реке – заняли берег Иордана вплоть до Бет – Бары.","25":"Были схвачены два мидьянских вождя – Ворон и Волк. И убили Ворона на Вороньем камне, а Волка – в Волчьей давильне. Израильтяне преследовали мидьянитян. Гедеону принесли из-за Иордана головы Ворона и Волка."},"8":{"1":"Ефремляне сказали Гедеону: «Как ты мог так поступить? Ты не позвал нас, когда шел на войну с мидьянитянами!» Они были в ярости.","2":"Но Гедеон сказал им: «Что мои дела по сравнению с вашими? Ефрему достались последние гроздья – они еще лучше, чем гроздья, собранные Авиэзером!","3":"В ваши руки Бог отдал мидьянских вождей – Ворона и Волка. Разве могут мои дела сравниться с вашими?» Когда Гедеон сказал им это, они успокоились.","4":"Гедеон и триста его воинов вышли к Иордану и переправились на тот берег. Они были измождены, но продолжали погоню.","5":"Гедеон сказал жителям Суккота: «Дайте моим людям хлеба. Они устали. Я преследую Зеваха и Цалмунну, мидьянских царей!»","6":"Но правители Суккота ответили: «Просишь, чтобы мы накормили твое войско? А ты уже схватил Зеваха и Цалмунну?»","7":"Гедеон сказал им: «А вот за это, когда Господь отдаст в мои руки Зеваха и Цалмунну, я пройдусь по вашим телам, как молотилкой, дикими колючками и сучьями!»","8":"Гедеон двинулся к Пенуэлу и обратился к его жителям с той же просьбой. Они ответили ему так же, как и жители Суккота.","9":"Гедеон сказал им: «Когда возвращусь с победой, я снесу вашу башню!»","10":"Зевах и Цалмунна стояли в Каркоре с пятнадцатитысячным войском. (Это было все, что осталось от воинства восточных племен. Сто двадцать тысяч воинов уже пали в бою.)","11":"Гедеон прошел дорогой кочевников – восточнее Новаха и Иогбехи – и напал на ничего не подозревавшее вражеское войско.","12":"Зевах и Цалмунна бежали. Гедеон погнался за ними и захватил их – Зеваха и Цалмунну, двух мидьянских царей. Все их войско бежало в страхе.","13":"Возвращаясь из похода, Гедеон, сын Иоаса, шел по Хересскому подъему.","14":"Он захватил и допросил одного юношу, из жителей Суккота, и тот составил ему список семидесяти семи правителей и старейшин города.","15":"Затем Гедеон пришел к жителям Суккота и сказал им: «Вот Зевах и Цалмунна! А вы насмехались надо мною, говорили, что раз я не поймал еще Зеваха и Цалмунну, вы не станете кормить моих изможденных людей!»","16":"И Гедеон велел схватить городских старейшин. Жителей Суккота он истерзал дикими колючками и сучьями,","17":"а в Пенуэле снес башню и перебил жителей города.","18":"Гедеон сказал Зеваху и Цалмунне: «Помните людей, которых вы убили на Фаворе?» Зевах и Цалмунна ответили: «Они были как ты. По виду – царские сыновья».","19":"И Гедеон сказал: «Это были мои братья, сыновья моей матери. Клянусь Господом, если бы вы пощадили их – и я вас пощадил бы!»","20":"Он велел своему старшему сыну Иетеру: «Убей их». Но тот был еще слишком молод и побоялся обнажить меч.","21":"«Убей нас ты, – сказали Зевах и Цалмунна. – Каждый делает то, что ему по силам». Тогда Гедеон убил их и забрал полумесяцы, которыми были украшены шеи их верблюдов.","22":"Израильтяне сказали Гедеону: «Правь нами, а потом пусть правит твой сын, потом твой внук. Ведь ты спас нас от мидьянитян!»","23":"Но Гедеон ответил: «Не буду я вами править. И сын мой не будет. Пусть вами правит Господь».","24":"И сказал им Гедеон: «Вот о чем я вас попрошу. Пусть каждый даст мне по одной серьге из своей добычи!» (Ведь враги были измаильтянами и носили золотые серьги.)","25":"Израильтяне отвечали: «Дадим!» Они расстелили плащ, и каждый положил на него по серьге из своей добычи.","26":"Золотые серьги, которые получил Гедеон, весили тысячу семьсот шекелей. А еще полумесяцы, подвески и пурпурные одеяния мидьянских царей, а еще ожерелья, что были на шеях у их верблюдов!","27":"Из золота этого Гедеон сделал эфод и поместил его в своем городе, в Офре. И был у всего Израиля блуд с этим эфодом! Эфод стал западней для Гедеона и его рода.","28":"Израиль взял верх над мидьянитянами, и те уже не смели поднять голову. И сорок лет, пока был жив Гедеон, в стране царил покой.","29":"Иеруббаал, сын Иоаса, вернулся и с тех пор жил дома.","30":"Семьдесят сыновей родилось у Гедеона – у него было много жен.","31":"И еще наложница, жившая в Шехеме, родила ему сына, которому он дал имя Авимелех.","32":"Гедеон, сын Иоаса, умер в глубокой старости и был похоронен в гробнице своего отца Иоаса, в Офре, что в наделе Авиэзера.","33":"После смерти Гедеона израильтяне снова стали блудить с Ваалами и сделали своим богом Баал – Берита.","34":"Не вспоминали израильтяне о Господе, Боге своем, который спас их от всех врагов, живших окрест!","35":"Да и роду Иеруббаала (Гедеона) не отплатили они добром за все то, что сделал Гедеон для Израиля."},"9":{"1":"Придя в Шехем, к братьям своей матери, Авимелех, сын Иеруббаала, обратился к ним и ко всему их роду с такими словами:","2":"«Скажите горожанам Шехема: „Что для вас лучше: чтобы над вами властвовали все семьдесят сыновей Иеруббаала – или один человек?\" И не забывайте, шехемцы, что я-то кость от кости вашей и плоть от плоти вашей!»","3":"Родственники его матери передали эти слова всем горожанам Шехема, и те поддержали Авимелеха, сказав: «Ведь он нам родня».","4":"Они дали Авимелеху семьдесят шекелей серебра из храма Баал – Берита. На эти деньги Авимелех нанял всяких оборванцев и негодяев. Во главе этого отряда","5":"он пришел в Офру, где жил род его отца, и убил своих братьев, сыновей Иеруббаала. Он убил на одном камне семьдесят человек! Уцелел лишь Иофам, младший сын Иеруббаала, – ему удалось спрятаться.","6":"Собрались все горожане Шехема и жители Бет – Милло – и возвели Авимелеха на царство. Это было у дуба, что близ священного камня, в Шехеме.","7":"Когда об этом сказали Иофаму, он поднялся на вершину горы Гаризим и оттуда прокричал: «Слушайте меня, горожане Шехема, тогда и Бог вас услышит!","8":"Собрались как-то раз деревья поставить над собой царя. „Царствуй над нами\", – предложили они маслине.","9":"Но та сказала: „А мое масло, которым чествуют богов и людей? Что же, мне больше не давать его? Только для того, чтобы возвыситься над другими деревьями?\"","10":"„Царствуй над нами ты\", – предложили деревья смоковнице.","11":"Но та сказала: „А мои сладкие плоды? Что же, мне больше не давать их? Только для того, чтобы возвыситься над другими деревьями?\"","12":"„Царствуй над нами ты\", – предложили деревья виноградной лозе.","13":"Но та сказала: „А мое вино, веселящее богов и людей? Что же, мне больше не давать его? Только для того, чтобы возвыситься над другими деревьями?\"","14":"„Царствуй над нами ты\", – сказали деревья терновому кусту.","15":"И тот ответил: „Если вы и вправду сделаете меня своим царем – что ж, приходите, укройтесь в моей тени. А не сделаете меня царем – от терновника разгорится огонь, который уничтожит кедры ливанские!\"","16":"Разве вы поступили честно и правильно, возведя Авимелеха на царство? Разве добром воздали вы Иеруббаалу и его роду? Такое ли воздаяние заслужил Иеруббаал?","17":"Мой отец воевал за вас, жизнью рисковал, чтобы спасти вас от мидьянитян!","18":"А вы теперь восстали против его рода и перебили его сыновей – убили на одном камне семьдесят человек! И поставили Авимелеха, сына его рабыни, царствовать над вами, горожанами Шехема, – из-за того лишь, что Авимелех вам родня.","19":"Если вы сейчас поступили честно и правильно, воздав так Иеруббаалу и его роду, – что ж, радуйтесь своему Авимелеху, и пусть он радуется вам!","20":"А если вы поступили неправильно и нечестно – пусть Авимелех разожжет огонь, который уничтожит горожан Шехема и жителей Бет – Милло! Пусть горожане Шехема и жители Бет – Милло разожгут огонь, который уничтожит Авимелеха!»","21":"Иофам бежал в Беэр, прочь от своего брата Авимелеха, и поселился там.","22":"Авимелех властвовал над Израилем три года.","23":"Но Бог послал злого духа возбудить вражду между Авимелехом и горожанами Шехема, и шехемцы отвернулись от Авимелеха.","24":"За гибель семидесяти сыновей Иеруббаала, за их пролитую кровь, должны были поплатиться и Авимелех, их брат, который их убил, и горожане Шехема, которые помогали ему в этом убийстве!","25":"Из вражды к Авимелеху горожане Шехема устраивали на вершинах окрестных гор засады. Сидевшие в засадах грабили всех, кто проходил мимо. Авимелеху донесли об этом.","26":"В Шехем пришел Гаал, сын Эведа, со своими родичами. Горожане Шехема понадеялись на него.","27":"Они пошли в виноградники, собрали урожай, давили виноград в давильнях, веселились и праздновали, а потом, в храме своего бога, ели, пили и поносили Авимелеха.","28":"Гаал, сын Эведа, говорил: «Что такое Авимелех? А что такое Шехем! Нам быть рабами Авимелеха? Это он, сын Иеруббаала, и его наместник Зевул должны служить людям Хамора, Шехемова отца! С какой стати мы будем служить Авимелеху?","29":"О, если бы я правил этими людьми – уж я-то прогнал бы Авимелеха!» И он бросил вызов Авимелеху: «Собирай войско, выходи на бой!»","30":"3евул, правитель города, услышал, что говорит Гаал, сын Эведа, – и пришел в ярость.","31":"Он тайно послал к Авимелеху вестников с таким сообщением: «В Шехем пришел Гаал, сын Эведа, со своими родичами. Они возбуждают горожан против тебя.","32":"Приходи ночью со своими людьми и устрой засаду за городом,","33":"а рано утром, как только взойдет солнце, напади на город. Гаал, со своими людьми, выйдет тебе навстречу – и попадет в твои руки».","34":"Ночью Авимелех выступил в поход со всем своим войском. Они расположились вокруг Шехема в засадах, четырьмя отрядами.","35":"Гаал, сын Эведа, стоял у городских ворот – и тут из засады появился Авимелех со своими людьми.","36":"Гаал увидел их и сказал Зевулу: «Какие-то люди спускаются с гор!» Зевул ответил: «Да нет, это не люди, это тени на горах».","37":"Но Гаал заговорил снова: «Это люди, они спускаются с Пупа Земли! И еще один отряд идет от дуба Прорицателей!»","38":"Тогда Зевул сказал ему: «А не ты ли говорил: „Кто такой Авимелех, с чего нам быть его слугами?\" Вот они – люди, которых ты презираешь! Иди и сражайся с ними!»","39":"Гаал, во главе горожан Шехема, вступил в бой с Авимелехом.","40":"Авимелех обратил их в бегство и преследовал до самых городских ворот; многие были убиты.","41":"После этого Авимелех расположился в Аруме. А Зевул прогнал Гаала с его родичами прочь из Шехема.","42":"На другой день шехемцы снова вышли из города. Об этом донесли Авимелеху.","43":"Он разделил свое войско на три отряда и устроил засаду. Увидев вышедших из города людей, он напал на них. Все они были перебиты:","44":"сам Авимелех со своим отрядом занял городские ворота, а другие два отряда устремились на вышедших из города и перебили их.","45":"Сражение между Авимелехом и шехемцами длилось целый день. Авимелех захватил город и убил всех его жителей. Он разрушил Шехем, а место это засеял солью.","46":"Когда жители Шехемской башни узнали о происходящем, они собрались в укреплении при храме Эл – Берита.","47":"Авимелеху донесли, что все они собрались в этом укреплении.","48":"Тогда Авимелех, приведя своих людей на гору Цалмон, топором нарубил сучьев, взвалил их на плечо и велел своим воинам: «Живее! Делайте, как я!»","49":"Нарубив сучьев, воины пошли за Авимелехом. Они обложили укрепление сучьями и подожгли. Так погибли все жители Шехемской башни, около тысячи мужчин и женщин.","50":"Потом Авимелех двинулся на Тевец, осадил город и взял его.","51":"В городе была неприступная башня; туда бежали все жители Тевеца, и мужчины и женщины. Они заперлись там и поднялись на самый верх.","52":"Авимелех подступил к башне, чтобы взять ее. Когда он был уже у дверей башни и собирался ее поджечь,","53":"какая-то женщина сбросила ему на голову ручной жернов и проломила ему череп.","54":"Авимелех тут же подозвал своего оруженосца и приказал ему: «Обнажи меч и убей меня. Пусть не говорят обо мне: „Его убила женщина!\"» Оруженосец пронзил его мечом, и Авимелех умер.","55":"Увидев, что он мертв, израильтяне разошлись по домам.","56":"Так Бог воздал Авимелеху за преступление, которое тот совершил против своего отца, – за убийство семидесяти братьев.","57":"И шехемцам Бог воздал за их злодеяния. Так сбылось проклятие Иофама, сына Иеруббаала."},"10":{"1":"После Авимелеха избавителем Израиля стал Тола, сын Пуа, сына Додо, из племени Иссахара. Он жил в Шамире, что в горах Ефрема.","2":"Тола был вождем Израиля двадцать три года. Затем он умер и был погребен в Шамире.","3":"После него был Яир из Галаада. Он был вождем Израиля двадцать два года.","4":"У него было тридцать сыновей, и у каждого – свой осел, и было у них тридцать сел. (Они и по сей день зовутся Яировы Деревни; находятся они в Галааде.)","5":"Яир умер и был погребен в Камоне.","6":"Израильтяне снова стали творить дела, ненавистные Господу: служили Ваалам и Астартам, богам арамеев, сидонян, моавитян, аммонитян и филистимлян. Оставили Господа, не служили Ему!","7":"Разгневался Господь на Израиль и отдал его в руки филистимлян и аммонитян.","8":"В тот год они разбили и поработили израильтян. На восемнадцать лет поработили они всех израильтян, что жили в Заиорданье – в земле амореев, в Галааде.","9":"Аммонитяне переправились через Иордан, чтобы начать войну также с Иудой, Вениамином и Ефремом. Беда пришла к израильтянам!","10":"Израильтяне воззвали к Господу: «Согрешили мы пред Тобою! Мы оставили своего Бога и стали служить Ваалам!»","11":"Господь ответил им: «Египтяне, амореи, аммонитяне, филистимляне –","12":"и сидоняне, и амалекитяне, и Маон – все они притесняли вас, и каждый раз Я вас спасал, стоило вам воззвать ко Мне!","13":"Но вы Меня оставляли и служили другим богам. Не стану Я больше спасать вас!","14":"Идите, взывайте к тем богам, которых вы избрали себе. Пусть они выручают вас из беды!»","15":"Израильтяне сказали Господу: «Согрешили мы! Делай с нами, что хочешь, только спаси нас сейчас!»","16":"Они отвергли всех чужих богов и стали служить Господу. И не потерпел Господь, чтобы израильтяне остались в беде.","17":"Аммонитяне собрались на войну и стали лагерем в Галааде. Израильтяне собрали войско и стали лагерем близ Мицпы.","18":"Войско, вожди Галаада – все говорили: «Кто поведет нас на битву с аммонитянами? Он и будет править Галаадом!»"},"11":{"1":"Иеффай из Галаада был могучий воин. Матерью его была продажная женщина, отцом – Галаад.","2":"Но у Галаада были и другие сыновья, от жены. Когда они выросли, то выгнали Иеффая и сказали ему: «Ты не получишь никакого наследства. Ты сын другой женщины».","3":"Иеффай бежал прочь от братьев и поселился в стране Тов. Там вокруг него собрались всякие оборванцы; под его началом они совершали набеги.","4":"И вот на Израиль напали аммонитяне.","5":"Когда аммонитяне напали на Израиль, старейшины Галаада пошли за Иеффаем в страну Тов.","6":"Они сказали Иеффаю: «Возвращайся, будь нашим вождем и веди нас на битву с аммонитянами!»","7":"Но он ответил им: «Раньше вы меня ненавидели, выгнали из отчего дома, а теперь, когда у вас беда, вы приходите ко мне!»","8":"Старейшины Галаада сказали: «Да, теперь мы пришли к тебе, чтобы ты повел нас на войну с аммонитянами. Ты станешь нашим правителем, правителем всего Галаада!»","9":"Иеффай сказал: «Хорошо. Если я, как вы просите, вернусь, буду воевать с аммонитянами, и Господь дарует мне победу, то я стану вашим правителем».","10":"Старейшины пообещали ему: «Господь нам свидетель! Клянемся, что так и будет!»","11":"Иеффай пошел со старейшинами Галаада. Войско сделало его своим начальником и вождем. В Мицпе, пред Господом, Иеффай повторил свое условие.","12":"Иеффай отправил к царю аммонитян послов, велев передать ему: «Чего ты от меня хочешь? Зачем идешь войной на мою землю?»","13":"Царь аммонитян дал послам Иеффая такой ответ: «Когда израильтяне шли из Египта, то захватили мои земли, от Арнона до Яббока и Иордана. Верни их по – хорошему!»","14":"Иеффай снова отправил послов к царю аммонитян,","15":"велев передать ему: «Так говорит Иеффай: Израиль не отнимал земли у моавитян и аммонитян.","16":"Уйдя из Египта, израильтяне шли по пустыне до самого моря Суф. Затем, придя в Кадеш,","17":"они отправили к царю Эдома послов с просьбой: „Позволь нам пройти по твоей земле!\" Но царь Эдома не позволил. Они просили царя Моава – и он не разрешил. Израильтянам пришлось остаться в Кадеше.","18":"Потом они двинулись по пустыне, обходя Эдом и Моав. Они прошли к востоку от Моава и стали лагерем за Арноном, не вступая в пределы Моава (Арнон – граница Моава).","19":"Израильтяне отправили к Сихону, царю амореев (царю Хешбона), послов с просьбой: „Позволь нам пройти через твою землю в нашу страну!\"","20":"Но Сихон не позволил израильтянам пройти по его земле. Он собрал все свое войско и, встав у Яхаца, вступил в сражение с израильтянами.","21":"Господь, Бог Израиля, отдал Сихона и все его войско в руки израильтян. Они разбили Сихона и заняли все земли амореев в той стране.","22":"Они завладели всей землей амореев – от Арнона до Яббока и от пустыни до Иордана.","23":"Так Господь, Бог Израиля, отобрал эту землю у амореев и отдал ее Своему народу, Израилю. И ты теперь хочешь отнять ее у нас?","24":"Ты владеешь землями, которые тебе дал твой бог, Кемош. А всей той землею, которую нам отдал наш Бог, Господь, будем владеть мы!","25":"Чем ты лучше Балака, Циппорова сына, царя Моава? А вот он не враждовал, не воевал с Израилем!","26":"Уже триста лет израильтяне живут в Хешбоне и окрестных селениях, в Ароэре и окрестных селениях и во всех селениях вдоль Арнона. Что же ты раньше не пытался отнять у нас эти земли?","27":"Я ничем тебя не обидел, а ты делаешь мне зло – идешь на меня войной. Пусть теперь Господь – Судия рассудит израильтян и аммонитян!»","28":"Но царь Аммона не внял этим словам Иеффая.","29":"И сошел на Иеффая дух Господа. Пройдя через Галаад, через землю Манассии, Иеффай пришел в Мицпе, что в Галааде, и оттуда двинулся на аммонитян.","30":"Иеффай дал Господу такой обет: «Если Ты даруешь мне победу над аммонитянами,","31":"то я, вернувшись домой с победой, отдам Тебе того, кто первым выйдет мне навстречу из дверей моего дома! Я принесу его в жертву всесожжения!»","32":"Иеффай двинулся на аммонитян и напал на них. Господь отдал их в его руки.","33":"Наголову разгромил их Иеффай – уничтожил двадцать селений, от Ароэра до подступов к Минниту, и до Авел – Керамима. Израиль взял верх над аммонитянами.","34":"Иеффай вернулся в Мицпу, домой, – и навстречу ему вышла его дочь, с бубнами и плясками. Она была у Иеффая единственная, кроме нее не было у него ни сыновей, ни дочерей.","35":"Увидев ее, он разорвал свои одежды и воскликнул: «Ох, дочка, что же ты со мной сделала! Ты навела на меня беду! Ведь Я дал Господу обет и не могу от него отказаться».","36":"Она ответила: «Отец мой! Если ты дал обет Господу, то поступи со мной так, как обещал Ему. Ведь Господь даровал тебе победу: ты отомстил своим врагам, аммонитянам!»","37":"И добавила: «Об одном прошу тебя: подожди два месяца. Я пойду в горы и там, вместе с подругами, буду плакать о девичестве своем!»","38":"Он сказал: «Иди». И отпустил ее на два месяца. Она пошла с подругами в горы и там плакала о девичестве своем.","39":"А через два месяца она вернулась к отцу, и он исполнил свой обет. Не суждено ей было познать мужчину. С тех пор у израильтян вошло в обычай,","40":"что каждый год девушки уходят на четыре дня и поют песни о дочери Иеффая из Галаада."},"12":{"1":"Ефремляне собрались, пришли в Цафон и сказали Иеффаю: «Почему ты не позвал нас, когда шел воевать с аммонитянами? За это мы сожжем тебя в твоем собственном доме!»","2":"Иеффай ответил им: «У меня и у моего народа была жестокая распря с аммонитянами. Я взывал к вам, но вы не помогли мне.","3":"Когда я понял, что от вас помощи не будет, то сам пошел на аммонитян. Я жизни своей не щадил! Господь отдал их в мои руки. Почему же теперь вы идете на меня войной?»","4":"Иеффай собрал всех жителей Галаада и вступил в бой с ефремляна – ми. Галаадцы разбили войско Ефрема. (Они кричали: «Беглецы – ефремляне! Галаад – меж Ефремом и Манассией!»)","5":"Галаадцы преградили ефремлянам путь, захватив броды через Иордан. Когда кто-нибудь из беглецов – ефремлян говорил: «Мне на тот берег!» – галаадцы у него спрашивали: «А ты не из племени Ефрема?» Он отвечал: «Нет!»","6":"Ему говорили: «Тогда скажи: „шибболет\"». А он не мог правильно выговорить и произносил: «сибболет». Его хватали и убивали – у брода через Иордан. Тогда были перебиты сорок две тысячи воинов из племени Ефрема.","7":"Иеффай был вождем Израиля шесть лет. Затем Иеффай из Галаада умер и был похоронен в своем селении, в Галааде.","8":"После него вождем Израиля был Ивцан из Вифлеема.","9":"У него было тридцать сыновей. Тридцать дочерей он выдал замуж и тридцать девушек взял в жены своим сыновьям. Он был вождем Израиля семь лет.","10":"Затем Ивцан умер и был похоронен в Вифлееме.","11":"После него вождем Израиля был Элон из племени Завулона. Он был вождем Израиля десять лет.","12":"Затем Элон из племени Завулона умер и был похоронен в Айялоне, что в земле Завулона.","13":"После него вождем Израиля был Авдон, сын Хиллела, из Пиратона.","14":"У него было сорок сыновей и тридцать внуков, которые ездили на семидесяти ослах. Он был вождем Израиля восемь лет.","15":"Затем Авдон, сын Хиллела, из Пиратона, умер и был похоронен в Пиратоне, что на Амалекитянских горах, в земле Ефрема."},"13":{"1":"Израильтяне снова стали творить дела, ненавистные Господу, и Господь на сорок лет отдал их в руки филистимлян.","2":"Был один человек, Маноах из Цоры, из племени Дана. Жена Маноаха была бесплодна, не было у нее детей.","3":"И явился ей ангел Господа. «Ты бесплодна, нет у тебя детей, – сказал он. – Но ты зачнешь и родишь сына.","4":"Смотри же, не пей ни вина, ни пива и не ешь нечистой пищи.","5":"Ты зачнешь и родишь сына! Он не должен стричь волосы, потому что он от рождения будет назореем Божьим. И он положит начало избавлению Израиля от филистимлян».","6":"Женщина пошла и сказала мужу: «Приходил ко мне человек Божий. Он был как Божий ангел: грозен был его вид. Я не спросила, откуда он; имени своего он мне не назвал.","7":"Он сказал мне: „Ты зачнешь и родишь сына. Не пей ни вина, ни пива и не ешь нечистой пищи. Твой сын от рождения до самой смерти будет назореем Божьим\"».","8":"Маноах стал просить Господа: «О Владыка! Пусть снова придет к нам тот человек Божий, Твой посланец! Пусть он скажет нам, что делать с ребенком, который у нас родится».","9":"Бог внял Маноаху. Ангел Господа вновь явился его жене. Та сидела в поле, Маноаха рядом не было.","10":"Она тут же побежала к мужу и сказала ему: «Снова пришел тот человек, что тогда приходил!»","11":"Маноах тотчас встал, последовал за женой и, подойдя к тому человеку, спросил: «Это ты говорил тогда с моей женой?» Тот ответил: «Да, я».","12":"Маноах спросил: «Когда твои слова сбудутся – как должен жить этот мальчик? Что он должен делать?»","13":"Ангел Господа ответил ему: «Пусть твоя жена не делает ничего того, что я запретил ей.","14":"Пусть не ест ничего, что рождает виноградная лоза, и не пьет вина и пива. Пусть не ест нечистой пищи. Пусть соблюдает все, что я велел ей!»","15":"«Побудь с нами еще! – сказал Маноах ангелу Господа. – Мы зарежем козленка и приготовим его для тебя». –","16":"«Даже если я побуду у тебя еще, – ответил ангел Господа, – я не стану есть твоей пищи. Но если ты хочешь принести Господу жертву всесожжения, то принеси ее». А Маноах еще не понял, что перед ним ангел Господа.","17":"«Как твое имя? – спросил Маноах у ангела. – Мы помянем тебя с благодарностью, когда твои слова сбудутся!»","18":"Но ангел Господа сказал: «Зачем тебе мое имя? Оно – тайна и чудо!»","19":"Взяв козленка и хлебное приношение, Маноах принес на скале жертву Господу. И вот, на глазах у Маноаха и его жены, Господь сотворил чудо.","20":"Когда над жертвенником поднялся к небу огонь, то ангел Господа, у них на глазах, вознесся в этом огне. Они пали ниц.","21":"И больше ангел не являлся ни Маноаху, ни его жене. Теперь Маноах знал: то был ангел Господа.","22":"«Мы умрем, – сказал Маноах жене. – Ведь мы видели Бога».","23":"Но жена возразила: «Если бы Господь хотел нас убить, Он не принял бы от нас ни всесожжения, ни хлебного приношения. Он не явил бы нам ничего и ничего бы нам не поведал!»","24":"Она родила сына и дала ему имя Самсон. Мальчик вырос; с ним пребывало Господне благословение.","25":"Впервые дух Господа овладел Самсоном, когда Самсон был в Махане - Дане, между Цорой и Эштаолом."},"14":{"1":"Как-то раз, придя в Тимну, Самсон увидел там одну филистимлянку.","2":"Вернувшись домой, он сказал отцу с матерью: «Я видел в Тимне одну филистимлянку. Возьмите ее мне в жены».","3":"Отец с матерью сказали: «Неужели среди твоих соплеменников, у твоего народа, нет женщин? Зачем ты идешь за женою к необрезанным, к филистимлянам?» – «Возьми мне в жены эту! – сказал Самсон отцу. – Она мне понравилась».","4":"Отец с матерью не знали, что все это было от Господа – Господь хотел, чтобы филистимляне сами дали повод для вражды. (В ту пору филистимляне властвовали над израильтянами.)","5":"Самсон отправился в Тимну вместе с отцом и матерью. Когда они дошли до виноградников Тимны, то навстречу Самсону, рыча, выбежал молодой лев.","6":"Дух Господа охватил Самсона, и Самсон голыми руками разорвал льва на куски, как козленка. Но отцу с матерью рассказывать об этом не стал.","7":"Самсон пришел в Тимну и поговорил с той женщиной. Понравилась она ему!","8":"Немного спустя Самсон снова пошел туда – взять эту женщину себе в жены. Он свернул посмотреть на убитого им льва и увидел там, в львином трупе, целый рой пчел и мед.","9":"Самсон набрал пригоршню меда и, лакомясь им, пошел своей дорогой. Вернувшись к отцу с матерью, он угостил их медом, но не сказал, что это мед из львиного трупа.","10":"И вот, отец Самсона пришел в дом той женщины. Самсон устроил там пир, как это принято у молодых людей.","11":"Увидев, что к ним пришел Самсон, хозяева позвали тридцать человек – быть его товарищами на пиру.","12":"Самсон сказал приглашенным: «Давайте-ка я загадаю вам загадку! Если за те семь дней, что длится пир, вы разгадаете ее и скажете мне ответ, я дам вам тридцать льняных рубах и тридцать смен одежды.","13":"А если не разгадаете, то вы мне дадите тридцать льняных рубах и тридцать смен одежды». Те ответили: «Ну, загадывай свою загадку. Послушаем!»","14":"И Самсон сказал: «Из того, кто ел, вышло то, что едят, из сильного вышло сладкое». Три дня филистимляне думали – не могли разгадать загадку.","15":"Наступил седьмой день пира – и они сказали жене Самсона: «Попробуй обхитрить своего мужа, чтобы он сказал нам разгадку. А не то мы сожжем и тебя, и твоих родных! Вы зачем нас позвали – чтобы обобрать?»","16":"Тогда она со слезами сказала Самсону: «Ты меня разлюбил! Не любишь ты меня! Ты загадал моим соплеменникам загадку и не хочешь сказать мне разгадку!» Самсон отвечал ей: «Я даже отцу с матерью не сказал разгадки. Неужели тебе скажу?»","17":"Все семь дней, что шел пир, она плакала и не отставала от него. И на седьмой день он сказал ей разгадку – так она его доняла! А она рассказала своим соплеменникам.","18":"И вот, на седьмой день, перед заходом солнца, жители города сказали Самсону: «Что слаще меда? Кто льва сильнее?» Самсон ответил им: «Не пахали бы вы на моей телке, не отгадать бы вам моей загадки!»","19":"Дух Господа охватил Самсона. Самсон пошел в Ашкелон, убил там тридцать человек, снял с них одежды и отдал тем, кто разгадал его загадку. Потом, разгневанный, он ушел домой, к отцу.","20":"А жену Самсона отдали тому, кто был у него дружкой на свадьбе."},"15":{"1":"Потом, уже в пору жатвы пшеницы, Самсон пришел навестить свою жену; он принес с собой козленка. Он сказал: «Я иду к своей жене, в ее комнату». Но ее отец не пустил Самсона","2":"и сказал: «Я думал, ты ее бросил. И я отдал ее одному из твоих товарищей. Но ее младшая сестра – та еще лучше! Бери младшую вместо нее!»","3":"Самсон сказал: «Ну, теперь филистимляне сами виноваты, что я буду мстить им!»","4":"Он пошел, поймал триста лисиц, связал их по две, хвост к хвосту, и привязал к хвостам каждой пары по факелу.","5":"Потом зажег факелы и пустил лисиц на филистимские поля – сжег и стога, и несжатый хлеб, и виноградники, и масличные деревья.","6":"«Кто это сделал?» – спросили филистимляне. Им ответили: «Самсон, зять того человека из Тимны, который отдал его жену другому!» Филистимляне пошли и сожгли эту женщину вместе с ее отцом.","7":"Самсон сказал: «Не успокоюсь, пока не отомщу вам сполна!»","8":"И он учинил филистимлянам страшное побоище. А потом ушел и поселился в пещере под Этамской скалой.","9":"Филистимляне пришли в Иудею, стали там лагерем и заняли Лехи.","10":"«Зачем вы идете на нас войной?» – спросили у них жители Иудеи. Те ответили: «Мы пришли, чтобы связать Самсона и отплатить ему за то, что он нам сделал!»","11":"Три тысячи жителей Иудеи пришли к пещере под Этамской скалой. Они сказали Самсону: «Ты ведь знаешь, что мы под властью филистимлян. Что же ты делаешь с нами?!» – «Я отплатил филистимлянам за то, что они сделали мне», – ответил Самсон.","12":"Жители Иудеи сказали: «Мы пришли, чтобы связать тебя и выдать филистимлянам». – «Поклянитесь, что вы не причините мне зла», – сказал им Самсон.","13":"«Не причиним! – сказали они. – Только свяжем тебя и отдадим филистимлянам. Мы не станем убивать тебя». Они связали его двумя новыми веревками и вывели из пещеры.","14":"Как только Самсон подошел к Лехи, филистимляне с криками устремились на него. И дух Господа охватил Самсона – веревки на его руках сделались как лен, объятый пламенем. Спали с рук его путы!","15":"На глаза Самсону попалась еще не высохшая ослиная челюсть. Он схватил ее – и перебил ею тысячу филистимлян.","16":"И сказал Самсон: «Челюстью осла перебил я врагов без числа! Тысячу человек – челюстью осла!»","17":"Сказав эти слова, он отбросил ослиную челюсть. А место это так и назвали – Рамат – Лехи.","18":"И одолела Самсона жажда. Он воззвал к Господу: «Ты даровал мне, рабу Твоему, эту великую победу! Так неужели я теперь умру от жажды, попаду в руки необрезанных?»","19":"Тогда Бог отверз возле Лехи расселину, и потекла оттуда вода. Самсон напился воды, и к нему вернулись силы – он остался в живых. И по сей день этот источник возле Лехи так и называется – Эн – ха – Коре .","20":"Самсон был вождем Израиля двадцать лет, во времена филистимского владычества."},"16":{"1":"Самсон пошел в Газу, там увидел продажную женщину и зашел к ней.","2":"Жители Газы узнали, что в город пришел Самсон. Они окружили то место, всю ночь подстерегали Самсона у городских ворот. Всю ночь они ждали, притаившись, и думали: «Вот рассветет – и убьем его!»","3":"Самсон полночи провел в постели. В полночь Самсон встал. Ухватился он за городские ворота, за их столбы, – и вырвал ворота вместе с засовом! Взвалил он ворота на плечи и отнес на вершину горы, что напротив Хеврона.","4":"Потом Самсон влюбился в женщину, которая жила в долине Сорек. Звали ее Далила.","5":"Филистимские правители пришли к Далиле и сказали ей: «Попробуй-ка обхитрить его: узнай, в чем секрет его великой силы. Как нам одолеть его, как связать его и справиться с ним? А мы дадим тебе по тысяче сто шекелей серебра каждый».","6":"Далила спросила у Самсона: «Скажи мне, в чем секрет твоей великой силы? Как тебя связать, как справиться с тобой?»","7":"Он отвечал: «Если связать меня семью сырыми, еще не высохшими жилами, я ослабею и стану как обычный человек».","8":"Филистимские правители принесли ей семь сырых, еще не высохших жил, и она связала Самсона.","9":"А в комнате у нее устроили засаду. «Самсон! За тобой пришли филистимляне!» – сказала ему Далила. И он разорвал эти жилы – так рвется скрученный лен, которого коснулся огонь! Секрет его силы так и не был раскрыт.","10":"«Ты меня обманул! – сказала Далила. – Ты мне неправду сказал! Ну, открой мне, чем тебя можно связать?»","11":"Он ответил: «Если связать меня новыми веревками, которые еще не были в работе, я ослабею и стану как обычный человек».","12":"Далила взяла новые веревки, связала его и сказала: «Самсон! За тобой пришли филистимляне!» (А в комнате была устроена засада.) И Самсон разорвал веревки, как нитки.","13":"«Ты все обманываешь меня! – сказала ему Далила. – Говоришь неправду! Ну, открой мне, чем тебя можно связать?» Он ответил: «Если ты вплетешь семь прядей моих волос в основу ткани на ткацком станке и подобьешь их деревянной спицей, я стану слабым, как обычный человек».","14":"Когда он уснул, Далила вплела семь прядей его волос в основу ткани на ткацком станке, подбила деревянной спицей и сказала: «Самсон! За тобой пришли филистимляне!» Он проснулся – и вырвал ткацкую спицу вместе с основой.","15":"«Говоришь, что любишь меня, а тайны своей мне не доверяешь! – сказала Далила. – Ты уже три раза меня обманул! Так и не открыл ты мне, в чем секрет твоей великой силы».","16":"Что ни день, донимала она его такими просьбами, допекала. Устал он от этого до смерти","17":"и открыл ей свою тайну. «Я никогда не стриг своих волос, – сказал Самсон. – С самого рождения я назорей Божий. Если меня остричь, моя сила оставит меня, я ослабею и стану как обычный человек».","18":"Поняла Далила, что он открыл ей свою тайну, и позвала филистимских правителей. «Теперь приходите! – передала она им. – Он открыл мне свою тайну». Филистимские правители пришли к ней, с серебром.","19":"Она усыпила Самсона у себя на коленях, потом позвала человека, и тот остриг Самсона – отрезал семь его прядей. Так впервые удалось ей справиться с Самсоном – сила оставила его.","20":"«Самсон! За тобой пришли филистимляне!» – сказала Далила. Самсон проснулся. «Вырвусь и на этот раз! – подумал он. – Выберусь!» Не знал он, что Господь его оставил.","21":"Филистимляне схватили Самсона и выкололи ему глаза. Они привели его в Газу и надели на него медные оковы. Там, в темнице, его заставили молоть зерно.","22":"Волосы Самсона снова начали отрастать.","23":"Филистимские правители собрались, чтобы совершить большое жертвоприношение своему богу Дагону и повеселиться. Они говорили: «Наш бог в наши руки отдал Самсона, что с нами воевал!»","24":"Глядя на Самсона, народ прославлял своего бога и говорил: «Наш бог в наши руки отдал того, кто с нами воевал, кто нашу землю разорял и груды трупов оставлял!» \"Развеселившись, филистимляне сказали: «Приведите Самсона, пусть он позабавит нас!» И вот, они вызвали Самсона из темницы и заставили его развлекать их. Самсона поставили между столбами дома.","26":"Он сказал своему поводырю: «Дай нащупать столбы, на которых держится дом, дай мне опереться на них».","27":"А дом был полон мужчин и женщин. Там были все филистимские правители, и еще три тысячи человек собрались на крыше, ожидая, что Самсон будет забавлять их.","28":"И воззвал Самсон к Господу: «Владыка Господь, вспомни обо мне! Теперь, Боже, дай мне силу! И я разом отомщу филистимлянам за оба моих глаза!»","29":"Он нащупал два срединных столба, на которых держался дом, и уперся в них обеими руками: правой рукой в один столб, левой – в другой.","30":"«Пусть я умру вместе с филистимлянами!» – воскликнул Самсон. Он изо всех сил налег на столбы, и дом обрушился – на филистимских правителей и на всех, кто там был. Самсон, умирая, убил еще больше врагов, чем при жизни!","31":"Братья Самсона, вместе со всем его родом, пришли и забрали тело Самсона. Они унесли его и похоронили между Цорой и Эштаолом, в гробнице его отца Маноаха. Самсон был вождем Израиля двадцать лет."},"17":{"1":"Был один человек, Михей с гор Ефрема.","2":"Он сказал своей матери: «Когда у тебя пропали тысяча сто шекелей серебра, ты произнесла проклятие, я сам это слышал. Но серебро у меня, это я взял его!» Мать сказала: «Да благословит Господь моего сына!»","3":"Сын вернул ей тысячу сто шекелей серебра, и она сказала: «Я посвящаю это серебро Господу, за моего сына! Пусть из этого серебра сделают изваяние, литую статую». «Я возвращаю тебе серебро!»","4":"И он вернул серебро матери. Она отдала двести шекелей серебра плавильщику, и тот сделал изваяние, литую статую. С тех пор это изваяние стояло в доме Михея.","5":"Так у этого человека, у Михи, появилось свое святилище. Сделав эфод и терафима, он посвятил в священники одного из своих сыновей.","6":"(В ту пору у Израиля не было царя и каждый делал, что хотел.)","7":"Был один юноша, родом из Вифлеема Иудейского, из племени Иуды. (Он был левит, проживающий в Вифлееме Иудейском.)","8":"Покинув Вифлеем, он отправился в путь – искал, где ему поселиться. Он пришел в горы Ефрема, к дому Михи.","9":"Миха спросил у него: «Откуда ты?» Тот ответил: «Я левит, из Вифлеема Иудейского. Вот, странствую, ищу, где мне поселиться».","10":"Миха сказал: «Оставайся у меня. Ты будешь у меня священником, станешь мне как отец. Я буду давать тебе десять шекелей серебра в год, а сверх того – одежду и еду». И левит остался:","11":"он согласился жить у Михи и стал ему как сын.","12":"Миха посвятил этого левита в священники. Юноша жил в доме Михи,","13":"и Миха говорил: «Теперь я уверен, что Господь благоволит ко мне. Ведь у меня в священниках – левит!»"},"18":{"1":"В ту пору у Израиля не было царя. В ту пору племя Дана искало, где бы ему поселиться (ведь ему, в отличие от других племен Израиля, так и не досталось надела).","2":"Сыны Дана отобрали из своего племени пять человек, пять могучих воинов из Цоры и Эштаола, и отправили их на разведку – разузнать все про эту страну. «Идите и все про эту страну разузнайте!» – велели этим пятерым. Они пришли в горы Ефрема, к дому Михи, и там заночевали.","3":"Когда они были около дома Михи, то услышали голос молодого левита. Они подошли и спросили: «Кто привел тебя сюда? Что ты делаешь здесь, чем занимаешься?» –","4":"«Меня нанял Миха. Я у него священник», – ответил тот. И рассказал им, как живется ему у Михи.","5":"Они сказали: «Мы хотим знать, будет ли нам удача в деле, ради которого мы отправились в путь. Вопроси Бога об этом!»","6":"И священник сказал им: «Идите с миром. Ваш путь – пред очами Господа!»","7":"Пятеро двинулись дальше, пришли в Лаиш и увидели, что люди в этом городе живут беспечно (как это в обычае у сидонян) – спокойно, ничего не опасаясь. В том краю не было никого, кто чинил бы им насилие, сгонял их с земли, властвовал над ними. От сидонян они были далеко, а из соседей ни с кем не общались.","8":"Когда пятеро воинов вернулись к своему племени, в Цору и Эштаол, у них спросили: «Ну что?»","9":"И они ответили: «Пойдем войной на этих людей! Мы видели, как хороша их земля. Чего вы ждете? Не медлите, выступим в поход и завладеем этой землей!","10":"Люди, на которых вы пойдете, живут, ничего не опасаясь. Бог отдает в ваши руки обширную страну – землю, где ни в чем нет недостатка!»","11":"Шестьсот воинов племени Дана выступили с оружием в руках из Цоры и Эштаола.","12":"Сперва они стали лагерем близ Кирьят – Иеарима, в Иудее. (Это место, рядом с Кирьят – Иеаримом, и по сей день зовется Махане - Дан.)","13":"Оттуда они двинулись в горы Ефрема. Когда они дошли до дома Михи,","14":"те пятеро, что ходили на разведку в Лаиш, сказали остальным: «А вы знаете, что в этих домах есть изваяние, литая статуя, эфод и терафим? Решайтесь!»","15":"Они свернули к дому молодого левита (то есть к дому Михи), вошли и поздоровались с левитом.","16":"Шестьсот воинов из племени Дана с оружием в руках стояли у ворот,","17":"а те пятеро, что ходили на разведку, вошли в дом и забрали изваяние, литую статую, эфод и терафима. Священник стоял у ворот, рядом стояло шестьсот воинов с оружием в руках,","18":"а те пятеро вошли в дом Михи и взяли изваяние, литую статую, эфод и терафима. Священник сказал им: «Что вы делаете?»","19":"Они отвечали: «Молчи, не говори ничего. Иди с нами. Будешь у нас священником, станешь нам как отец. У кого лучше служить священником: у какого-то человека, в его дому, или у целого племени, у одного из родов Израиля?»","20":"Священник обрадовался. Взяв эфод, терафима и изваяние, он присоединился к отряду.","21":"И воины двинулись дальше. Свои семьи со всем имуществом и свои стада они пропустили вперед.","22":"Когда воины племени Дана были уже далеко от дома Михи, их догнали люди, которых Миха созвал из соседних домов.","23":"Услыхав позади крики, воины племени Дана обернулись и сказали Михе: «Ты что? Ты зачем созвал людей?»","24":"Миха сказал: «Вы забрали бога, которого я сделал, забрали священника и ушли! Ничего у меня не осталось! И еще говорите: „Ты что?\"»","25":"Ему ответили: «Чтоб голоса твоего мы больше не слышали! Наши люди и так злы. Набросятся на вас – и тебе и твоей родне конец придет!»","26":"И воины племени Дана пошли дальше. Миха увидел, что сила на их стороне, повернулся и пошел домой.","27":"Забрав то, что сделал Миха, забрав священника, который служил у Михи, они двинулись на Лаиш. Там люди жили спокойно, ничего не опасаясь, – и воины племени Дана перебили их, а город сожгли.","28":"Никто не пришел на помощь жителям Лаиша: от сидонян они были далеко, а из соседей ни с кем не общались. Лаиш находится в Бет – Реховской долине. Сыны Дана заново отстроили этот город и стали там жить.","29":"Они дали ему имя Дан, в честь своего прародителя Дана, одного из сыновей Израиля. А прежнее имя города – Лаиш.","30":"Сыны Дана поставили изваяние у себя. Сперва их священником был Ионафан, сын Гершома, сына Моисея, а затем, вплоть до времен изгнанья, – потомки Ионафана.","31":"Поставили они у себя изваяние, сделанное Михой, – и оно стояло у них все то время, что храм Бога был в Силоме."},"19":{"1":"В ту пору не было у Израиля царя. На дальних склонах гор Ефрема жил один левит. Он взял себе наложницу из Вифлеема Иудейского.","2":"Наложница поссорилась с ним и вернулась в дом отца, в Вифлеем Иудейский. Прошло около четырех месяцев.","3":"Взяв с собою слугу и пару ослов, левит отправился за своей наложницей – уговорить ее, чтобы она вернулась. Она привела его в дом отца; тот, увидев зятя, встретил его с радостью","4":"и уговорил остаться и погостить. Трое суток они ели, пили, спали там,","5":"а на четвертый день, рано утром, левит собрался в дорогу. Тесть сказал ему: «Поешь, подкрепись немного перед дорогой».","6":"Они сели, поели вдвоем, выпили, и тесть сказал левиту: «Останься, переночуй у меня. Отдохни!»","7":"Левит хотел идти, но тесть настаивал, и левит остался еще на одну ночь.","8":"На пятый день, рано утром, левит вновь собрался в дорогу, но тесть сказал ему: «Поешь!» И они просидели вдвоем за трапезой до самого вечера.","9":"Потом левит стал собираться в путь, вместе с наложницей и слугой. Тесть сказал ему: «Гляди, уже вечереет! Оставайся на ночь, ведь сумерки наступают. Переночуешь здесь, отдохнешь, а завтра, рано утром, отправитесь в путь, к тебе домой».","10":"Но левит больше не хотел оставаться на ночь и пустился в путь. Он дошел до города Евуса (то есть Иерусалима). С ним была пара навьюченных ослов и наложница.","11":"Когда они подошли к Евусу, день уже кончался. Слуга левита сказал своему хозяину: «Может, свернем в этот евусейский город, переночуем там?»","12":"Но хозяин сказал: «Нет, мы не будем заходить в город чужаков; они не израильтяне! Мы пойдем в Гиву ».","13":"Он предложил: «Давай дойдем до одного из этих селений, Гивы или Рамы, там и заночуем».","14":"И они пошли дальше. Солнце закатилось, когда они были близ Гивы, что в земле Вениамина.","15":"Они свернули в Гиву, чтобы переночевать, и сели на городской площади. Но никто не приглашал их к себе на ночлег.","16":"Меж тем с поля, после работы, возвращался на исходе дня один старик. Он жил в Гиве, но родом был с гор Ефрема (а Гиву населяли люди из племени Вениамина).","17":"Старик увидел на городской площади путника и спросил его: «Куда ты идешь и откуда?»","18":"Тот ответил: «Мы идем из Вифлеема Иудейского на ту сторону гор Ефрема – я родом оттуда. Я ходил в Вифлеем Иудейский и теперь возвращаюсь домой. Никто не приглашает меня к себе!","19":"А ведь у нас есть солома и корм для ослов. Есть у нас, рабов твоих, еда и вино – и для меня, и для нее, рабы твоей, и для моего слуги. Нам ничего не нужно!»","20":"Старик сказал ему: «Не беспокойся! Я дам вам все, что нужно; не ночуйте на улице!»","21":"Он привел их к себе домой и дал корм их ослам. Путники омыли ноги и сели за трапезу.","22":"Путники отдыхали – и тут жители города, люди злые и негодные, обступили дом, стали ломиться в дверь и требовать от старика – хозяина вывести гостя, чтобы они надругались над ним.","23":"Хозяин вышел к ним и принялся их уговаривать: «Братья, не надо, не совершайте преступления! Ведь он мой гость, не делайте с ним этой мерзости!","24":"Лучше я вам отдам и мою дочь – девственницу, и его наложницу. Насилуйте их, делайте с ними, что хотите. Только не творите такой мерзости с моим гостем!»","25":"Но те и слушать его не желали. Тогда левит схватил свою наложницу и вывел к стоявшим на улице. Те над ней надругались, глумились над нею всю ночь, до утра, – и лишь на заре отпустили ее.","26":"Чуть свет, вернулась она к дому, где был ее господин, упала на пороге и лежала там до восхода солнца.","27":"Настало утро. Господин ее встал и открыл дверь, чтобы идти дальше своей дорогой, – и увидел, что прямо у двери, держась руками за порог, лежит его наложница.","28":"Он сказал ей: «Вставай, пойдем!» Но ответа не было. Он взвалил ее тело на осла и отправился домой.","29":"Придя домой, он взял тесак, разрубил мертвое тело на двенадцать частей и разослал их во все пределы Израиля.","30":"И все, кто видел это, говорили: «С тех пор как израильтяне ушли из Египта и до сего дня, не бывало, не случалось ничего подобного! Смотрите! Давайте же думать, давайте примем решение!»"},"20":{"1":"Все израильтяне, вся община – жители всех земель от Дана до Беэр – Шевы и жители Галаада – все, как один человек, собрались в Мицпу и предстали пред Господом.","2":"Там были все вожди народа, вожди всех племен Израиля. Там собрался народ Божий – четыреста тысяч пеших воинов, вооруженных мечами.","3":"Племя Вениамина узнало, что израильтяне собрались в Мицпе. Израильтяне спросили: «Как свершилось это злодеяние?»","4":"И левит, муж убитой женщины, ответил: «Я пришел со своей наложницей в Гиву, что в земле Вениамина, на ночлег.","5":"Ночью горожане Гивы пришли, окружили дом, где я был, и собирались убить меня. Они изнасиловали мою наложницу. Она умерла.","6":"Я разрубил ее тело на части и разослал их по всем владениям израильтян. Ведь совершена гнусность, мерзость, оскорбляющая Израиль!","7":"А теперь, израильтяне, думайте и решайте!»","8":"И весь народ, как один человек, постановил: «Мы не разойдемся по шатрам, домой не пойдем.","9":"Вот как мы поступим с Гивой (следуя указаниям жребия).","10":"Мы отберем людей из всех племен Израиля – по десять человек из сотни, по сто человек из тысячи, по тысяче из десяти тысяч – чтобы они раздобыли припасы для всего войска. Войско пойдет на Гиву, что в земле Вениамина, и отомстит ее жителям за эту гнусность, оскорбляющую Израиль!»","11":"И вот израильтяне, все как один, вместе, подошли к Гиве.","12":"Племена Израиля отправили ко всему племени Вениамина послов, велев передать такие слова: «Как могло свершиться у вас подобное злодеяние?","13":"Выдайте нам этих негодяев из Гивы! Мы убьем их – и очистим Израиль от скверны». Но люди племени Вениамина не послушали израильтян, братьев своих.","14":"Они собрались из всех своих селений в Гиву, чтобы воевать с израильтянами.","15":"Эти селения выставили для войны двадцать шесть тысяч человек, вооруженных мечами, а еще семьсот отборных воинов выставили сами жители Гивы.","16":"(В этом войске было семьсот отборных воинов – левшей, которые, метнув камень из пращи, без промаха попадали в волос!)","17":"А израильтян, без племени Вениамина, собралось четыреста тысяч человек, вооруженных мечами. Все они были опытными воинами.","18":"Израильтяне пришли в Бет – Эль и вопросили Бога: «Кто поведет нас на войну с племенем Вениамина?» Господь ответил: «Вас поведет Иуда».","19":"Утром израильтяне стали лагерем близ Гивы.","20":"Готовясь к бою с племенем Вениамина, израильтяне построились напротив Гивы.","21":"Воины племени Вениамина вышли из Гивы, напали на них – и перебили в тот день двадцать две тысячи израильтян.","22":"Собравшись с силами, израильтяне вновь построились для битвы – там же, где и накануне.","23":"(Они пошли и до вечера плакали пред Господом, а потом вопросили Его: «Продолжать ли нам войну с нашими братьями, племенем Вениамина?» И Господь ответил: «Воюйте!»)","24":"Итак, на второй день израильтяне вновь двинулись на воинов племени Вениамина.","25":"А те и в этот день вышли из Гивы, напали на израильтян – и перебили еще восемнадцать тысяч воинов, вооруженных мечами.","26":"И пошли тогда израильтяне, все их войско, в Бет – Эль. Там сидели они пред Господом, плакали и постились – весь день, до вечера. Они принесли Господу жертвы всесожжения и пиршественные жертвы.","27":"Затем израильтяне вопросили Господа. (В ту пору ковчег договора с Богом был там,","28":"и служил при нем в то время Пинехас, сын Элеазара, сына Аарона.) «Продолжать ли нам войну с нашими братьями, племенем Вениамина? – спросили израильтяне. – Или прекратить войну?» И Господь ответил: «Воюйте! Завтра Я отдам их в ваши руки!»","29":"И тогда израильтяне устроили засады вокруг Гивы.","30":"На третий день израильтяне вновь вышли на бой с племенем Вениамина и построились напротив Гивы, как и раньше.","31":"Воины племени Вениамина напали на израильтян – и удалились от своего города. Они, как и прежде, стали убивать израильтян, гнались за ними вдоль дороги, соединяющей Бет – Эль и Гиву. Они убили около тридцати израильтян.","32":"Воины Вениамина думали: «Мы их бьем, как прежде!» А израильтяне задумали, обратившись в бегство, увести врага по дорогам подальше от города.","33":"(Войско израильтян, снявшись с места, построилось близ Баал – Тамара, а отряд, сидевший в засаде к западу от Гивы, устремился на Гиву.","34":"Десять тысяч лучших воинов, собранных со всего Израиля, двинулись на Гиву. Бой был тяжелым. Воины племени Вениамина не думали, что их ждет поражение,","35":"но Господь сделал так, что они были разбиты израильтянами. В тот день израильтяне перебили в их войске двадцать пять тысяч сто человек, вооруженных мечами.)","36":"Воинам Вениамина казалось, что израильтяне разбиты. А израильтяне отступали перед войском Вениамина, потому что полагались на воинов, сидевших в засаде близ Гивы.","37":"И вот эти воины устремились из засады на Гиву – они ворвались в город и перебили всех, кто был там!","38":"А между израильским войском и людьми в засаде было условлено: когда те разожгут огонь и над городом поднимется дым,","39":"то войско израильтян повернет обратно. Воины племени Вениамина убили уже около тридцати человек и думали: «Израильтяне разбиты, как и в первом сражении».","40":"И вот тут-то над городом поднялся столб дыма! Обернулись воины Вениамина – и увидели, что весь их город горит, дым от него восходит к небесам!","41":"Войско израильтян повернуло обратно, и воинов Вениамина охватил ужас: они поняли, что потерпели поражение.","42":"Они побежали от израильтян по дороге, ведущей в пустыню. За ними погнались. Со стороны города подошел отряд израильтян – и стал истреблять окруженных.","43":"Воины Вениамина были окружены. Их преследовали без передышки и загнали в пустыню, что восточнее Гивы.","44":"Они потеряли восемнадцать тысяч человек – и все это были могучие воины!","45":"Воины Вениамина бежали в пустыню, к скале Риммон. Когда они бежали по дорогам, было убито еще пять тысяч человек. Израильтяне преследовали их до самого Гидома – и перебили еще две тысячи человек.","46":"Всего в тот день из войска Вениамина пало двадцать пять тысяч человек, вооруженных мечами, – и все это были могучие воины!","47":"Воины Вениамина бежали в пустыню, к скале Риммон. Их было шестьсот человек; они оставались там четыре месяца.","48":"А израильтяне вернулись в землю племени Вениамина и уничтожили там и селения, и людей, и скот. Все селения были сожжены."},"21":{"1":"Когда израильтяне собрались в Мицпе, они поклялись не выдавать своих дочерей за людей из племени Вениамина.","2":"А теперь израильтяне пришли в Бет – Эль и, сидя пред Господом, громко и горько плакали до самого вечера.","3":"Они говорили: «О Господь, Бог Израиля! Зачем же это было нужно? Теперь Израиль недосчитывается одного племени!»","4":"На следующий день, рано утром, израильтяне воздвигли там жертвенник и принесли на нем жертвы всесожжения и пиршественные жертвы.","5":"Они спрашивали друг у друга: «Есть ли в племенах Израиля люди, которые не пришли, когда мы собирались пред Господом?» (А они дали великую клятву, что все, кто не пришел в Мицпу предстать пред Господом, будут преданы смерти.)","6":"Израильтянам стало жаль своих братьев из племени Вениамина. «Теперь Израиль лишился одного из племен! –","7":"говорили они. – И как найти жен для тех из них, кто уцелел? Ведь мы поклялись Господом не выдавать своих дочерей за них!»","8":"Они спрашивали друг у друга: «Есть ли в племенах Израиля хоть кто-нибудь, кто не пришел в Мицпу предстать пред Господом?» И оказалось: из жителей Явеша Галаадского ни один человек не присоединил – ся к войску, никого из них не было на том собрании.","9":"Собрали все войско – из Явеша Галаадского не было никого!","10":"Тогда община Израиля послала в этот город двенадцать тысяч воинов, велев им: «Идите и перебейте жителей Явеша Галаадского, вместе с женщинами и детьми.","11":"Вот вам приказ: предайте заклятью и уничтожьте там всех мужчин и всех женщин, познавших мужчину!»","12":"Среди жителей Явеша Галаадского нашлось четыреста девушек, не познавших мужчину. Их привели в стан израильтян – в Силом, что в Ханаане.","13":"Потом община Израиля отправила послов с предложением мира к тем воинам из племени Вениамина, которые укрывались у скалы Риммон.","14":"Воины Вениамина вернулись домой, и им отдали в жены девушек из Явеша Галаадского. Но девушек не хватило на всех.","15":"Народу жаль стало племени Вениамина. Господь лишил израильтян одного из их племен!","16":"Старейшины общины задумались: «Как найти жен для тех из них, кто уцелел? Ведь все женщины из племени Вениамина перебиты».","17":"Они сказали: «Надел спасшихся вениамитян должен остаться за Вениамином. Ни одно из племен Израиля не должно исчезнуть!","18":"Но мы не можем дать им в жены наших дочерей». (Ведь израильтяне поклялись: «Всякий, кто отдаст дочь в жены человеку из племени Вениамина, будет проклят!»)","19":"И они вспомнили: «Каждый год в Силоме бывает праздник Господа». (Это к северу от Бет – Эля, на восток от дороги, ведущей из Бет – Эля в Шехем, и к югу от Левоны.)","20":"Они велели людям из племени Вениамина: «Идите туда и спрячьтесь в виноградниках.","21":"Когда увидите, что девушки Силома вышли водить хороводы, то выбегайте и хватайте их. Пусть каждый из вас возьмет себе одну из них – и возвращайтесь в землю Вениамина.","22":"а когда их отцы или братья придут к нам с жалобой, мы их попросим: „Оставь – те нам ваших дочерей! Не все из нас смогли добыть себе жену на войне! а вы не могли отдать своих дочерей сами – на вас был бы грех!\"»","23":"Так и сделали люди из племени Вениамина: каждый взял себе в жены одну из похищенных – одну из девушек, водивших хороводы. Затем они вернулись в свой надел, вновь отстроили свои селения и стали жить в них.","24":"Израильтяне тоже разошлись по домам – каждый вернулся к своему племени, в свой род. Все разошлись по своим наделам.","25":"В ту пору у Израиля не было царя и каждый делал, что хотел."}};
